import json, re, collections, sys

def norm(s):
    s = re.sub('[أإآ]', 'ا', s); s = s.replace('ة', 'ه').replace('ى', 'ي'); s = re.sub(r'[ًٌٍَُِّْـ]', '', s)
    s = re.sub(r'(\d)([^\d\s.,*×/])', r'\1 \2', s)
    s = re.sub(r'بدون اضافه سكر|بدون سكر مضاف|بدون سكر|زيرو سكر|خالي من السكر|قليل السكر|سكر اقل|خالي السكر', ' ', s)
    s = re.sub(r'[.\-_/*+()]', ' ', s)
    return ' ' + re.sub(r'\s+', ' ', s).strip() + ' '

PRE = r'(?<=\s)(?:و|ب|بال|ال|لل|وال|ل|فال)?'
def rx(words):
    """كلمات مفصولة بـ| ؛ الكلمة اللي تنتهي بـ! لازم تكون كلمة كاملة"""
    out = []
    for w in words.split('|'):
        w = w.strip()
        if not w: continue
        whole = w.endswith('!')
        w = w.rstrip('!').replace(' ', r'\s?')
        out.append(w + (r'(?=\s)' if whole else ''))
    return re.compile(PRE + '(?:' + '|'.join(out) + ')')

