BRAND_DRINKS = rx('ريتا!|ربيع!|الربيع!|جواد!|لاكي!|راني!|ديو!|نوفا!|هنا!|تانيا!')
FRUIT = re.compile(r'برتقال|مانجو|جواف|رمان|تفاح|عنب|خوخ|فراول|ليمون|اناناس|كرز|توت|مشمش|فواكه')
VOL = re.compile(r'\d\s?(?:مل|ملي|لتر|ل!)|لتر')

def classify(name):
    n = norm(name)
    for cat, r in OVR:
        if r.search(n): return cat, 'ovr'
    if re.search(r'صابون.*\d\s?(?:كيلو|كجم|ك)(?=\s)', n): return 'clean', 'ovr'
    best = None
    for cat, r in T.items():
        m = r.search(n)
        if m and (best is None or m.start() < best[1] or (m.start() == best[1] and len(m.group(0)) > best[2])):
            best = (cat, m.start(), len(m.group(0)))
    if best: return best[0], 'type'
    if BRAND_DRINKS.search(n): return 'drinks', 'brand'
    if FRUIT.search(n) and VOL.search(n): return 'drinks', 'fruit'
    return None, 'none'

if __name__ == '__main__':
    d = json.load(open(sys.argv[1] if len(sys.argv) > 1 else 'data.json'))
    res = []
    for p in d['products']:
        if p['cat'] == 'print': continue
        c, how = classify(p['name'])
        if c and ':' in c: nc, ns = c.split(':')
        else: nc, ns = c, None
        res.append((p, nc, ns, how))
    json.dump([(p['id'], nc, ns, h) for p, nc, ns, h in res], open('cls.json', 'w'))
    out = [f"{p['cat']}>{nc}{':'+ns if ns else ''} {p['name']}" for p, nc, ns, h in res if nc and (nc != p['cat'] or (ns and ns != p.get('sub')))]
    out.sort(); open('moves.txt', 'w').write('\n'.join(out))
    none = [f"{p['cat']} {p['name']}" for p, nc, ns, h in res if not nc]
    none.sort(); open('none.txt', 'w').write('\n'.join(none))
    print('moves', len(out), 'unmatched', len(none))
    print(collections.Counter(l.split(' ')[0] for l in out).most_common(50))
